 :score OR vcclassname IN ( SELECT vcclassname FROM transaction_classes WHERE skipprocessing = -2 ) ) AND dtcreateddatetime BETWEEN ((CURRENT_TIMESTAMP - INTERVAL ''1 day'') AT TIME ZONE :timeZone) AND CURRENT_TIMESTAMP AT TIME ZONE :timeZone  and ilivemessageid > :iLiveMessageID and itenantid = :tenantid ORDER BY ilivemessageid DESC LIMIT 1000;"
